df=pd.DataFrame(rows);df.to_csv(o/"participants.csv",index=False);summary=df.groupby("method").mean(numeric_only=True).drop(columns="subject").sort_values("macro_f1",ascending=False);summary.to_csv(o/"summary.csv");wide=df.pivot(index="subject",columns="method",values="macro_f1");primary_controls=[s for s in protocol["scopes"] if s!="future_groups"]+["frozen","frozen_ema08","frozen_ema05","static","static_ema08","static_ema05"];best=max(primary_controls,key=lambda k:summary.loc[k,"macro_f1"]);candidate=float(summary.loc["future_groups","macro_f1"]);positive=int((wide.future_groups>wide.frozen).sum());advance=candidate>summary.loc[best,"macro_f1"] and positive>=3
